int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    // We'll keep track of file IDs and the sectors they occupy.
    // Also, we'll maintain a set of free sectors.
    // Since writing is sequential and we can reuse deleted sectors,
    // we need to keep track of the next free sector to write to.

    map<int, vector<int>> fileSectors; // file id -> list of sectors
    set<int> freeSectors;              // sectors that are free
    int nextFree = 0;                  // next sector to write if no free sectors

    // To quickly know which file occupies a sector, we can keep an array.
    // But sector indices can go up to large numbers (up to 10^9? not given, but we need dynamic).
    // Use a map for sector -> file id.
    map<int, int> sectorOwner;

    while (n--) {
        string cmd;
        cin >> cmd;

        if (cmd == "WRITE") {
            int fileId, size;
            cin >> fileId >> size;
            vector<int> sectors;
            for (int i = 0; i < size; ++i) {
                int sector;
                if (!freeSectors.empty()) {
                    auto it = freeSectors.begin();
                    sector = *it;
                    freeSectors.erase(it);
                } else {
                    sector = nextFree++;
                }
                sectorOwner[sector] = fileId;
                sectors.push_back(sector);
            }
            fileSectors[fileId] = sectors;
        } else if (cmd == "DELETE") {
            int fileId;
            cin >> fileId;
            if (fileSectors.count(fileId)) {
                for (int sector : fileSectors[fileId]) {
                    sectorOwner.erase(sector);
                    freeSectors.insert(sector);
                }
                fileSectors.erase(fileId);
            }
        } else if (cmd == "READ") {
            int sector;
            cin >> sector;
            if (sectorOwner.count(sector)) {
                cout << sectorOwner[sector] << "\n";
            } else {
                cout << "-\n";
            }
        }
    }

    return 0;
}

