#include <bits/stdc++.h>
using namespace std;

struct Segment {
    int l, r;   // inclusive
    int id;     // 0 = free, >0 = file id
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    if (!(cin >> n)) return 0;

    // We model the disk as disjoint segments on [1, +inf).
    // Initially everything is free: [1, INF).
    const int INF = 2000000000;

    map<int, Segment> segs; // key = l
    segs[1] = {1, INF, 0};

    auto split = [&](int pos) {
        auto it = prev(segs.upper_bound(pos));
        if (it->second.l == pos) return it;
        Segment s = it->second;
        if (pos > s.r) return next(it);
        it->second.r = pos - 1;
        segs[pos] = {pos, s.r, s.id};
        return segs.find(pos);
    };

    auto mergeAround = [&](map<int, Segment>::iterator it) {
        if (it == segs.end()) return;

        // merge with previous
        while (it != segs.begin()) {
            auto prv = prev(it);
            if (prv->second.id == it->second.id && prv->second.r + 1 == it->second.l) {
                prv->second.r = it->second.r;
                segs.erase(it);
                it = prv;
            } else break;
        }

        // merge with next
        while (true) {
            auto nxt = next(it);
            if (nxt != segs.end() && nxt->second.id == it->second.id && it->second.r + 1 == nxt->second.l) {
                it->second.r = nxt->second.r;
                segs.erase(nxt);
            } else break;
        }
    };

    for (int i = 0; i < n; ++i) {
        char cmd;
        cin >> cmd;

        if (cmd == 'W') {
            int id, len;
            cin >> id >> len;

            int need = len;
            auto it = segs.begin();
            while (need > 0) {
                if (it->second.id != 0) {
                    ++it;
                    continue;
                }

                int take = min(need, it->second.r - it->second.l + 1);
                int L = it->second.l;
                int R = L + take - 1;

                split(R + 1);
                auto mid = split(L);
                mid->second.id = id;
                mergeAround(mid);

                need -= take;
                it = segs.upper_bound(R);
            }
        } else if (cmd == 'D') {
            int id;
            cin >> id;

            for (auto it = segs.begin(); it != segs.end(); ) {
                if (it->second.id == id) {
                    it->second.id = 0;
                    auto cur = it++;
                    mergeAround(cur);
                } else {
                    ++it;
                }
            }
        } else if (cmd == 'R') {
            int x;
            cin >> x;

            auto it = prev(segs.upper_bound(x));
            cout << it->second.id << '\n';
        }
    }

    return 0;
}

