public class FileSystem {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);

        int n = Integer.parseInt(br.readLine().trim());

        // TreeSet to maintain free gaps: each gap is [start, end) (end exclusive)
        TreeSet<int[]> freeGaps = new TreeSet<>((a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(a[1], b[1]);
        });
        // Initially one free gap from sector 0 to infinity (we'll cap at needed size)
        // We'll manage dynamically: start with empty and add gap when needed

        // Map from fileId to list of written sectors (for deletion)
        Map<Integer, List<Integer>> fileSectors = new HashMap<>();
        // Array to store which file occupies each sector (dynamic)
        // We'll use a TreeMap to store intervals of file allocations: sector -> fileId
        TreeMap<Integer, Integer> sectorToFile = new TreeMap<>();

        // We'll keep a pointer to the current end of allocated space
        int currentEnd = 0;

        for (int i = 0; i < n; i++) {
            String line = br.readLine().trim();
            if (line.isEmpty()) continue;
            String[] parts = line.split(" ");
            char cmd = parts[0].charAt(0);

            if (cmd == 'W') {
                int fileId = Integer.parseInt(parts[1]);
                int size = Integer.parseInt(parts[2]);

                List<Integer> sectors = new ArrayList<>();
                int toWrite = size;

                // First try to fill from free gaps
                while (toWrite > 0 && !freeGaps.isEmpty()) {
                    int[] gap = freeGaps.first();
                    int gapStart = gap[0];
                    int gapEnd = gap[1];
                    int gapSize = gapEnd - gapStart;

                    if (gapSize > 0) {
                        int take = Math.min(toWrite, gapSize);
                        // Write from gapStart to gapStart + take
                        for (int s = gapStart; s < gapStart + take; s++) {
                            sectors.add(s);
                            sectorToFile.put(s, fileId);
                        }
                        if (take == gapSize) {
                            freeGaps.pollFirst();
                        } else {
                            freeGaps.pollFirst();
                            freeGaps.add(new int[]{gapStart + take, gapEnd});
                        }
                        toWrite -= take;
                    } else {
                        freeGaps.pollFirst();
                    }
                }

                // If still need space, allocate new sectors at the end
                if (toWrite > 0) {
                    int start = currentEnd;
                    for (int s = start; s < start + toWrite; s++) {
                        sectors.add(s);
                        sectorToFile.put(s, fileId);
                    }
                    currentEnd += toWrite;
                }

                fileSectors.put(fileId, sectors);

            } else if (cmd == 'D') {
                int fileId = Integer.parseInt(parts[1]);
                List<Integer> sectors = fileSectors.remove(fileId);
                if (sectors != null) {
                    // Sort sectors to merge into free gaps
                    Collections.sort(sectors);
                    for (int s : sectors) {
                        sectorToFile.remove(s);
                    }
                    // Add these sectors as free gaps
                    for (int s : sectors) {
                        // Find if adjacent to existing gaps
                        Integer left = sectorToFile.lowerKey(s);
                        Integer right = sectorToFile.higherKey(s);
                        // Actually we need to check freeGaps for adjacency
                        // We'll do a merge approach
                    }
                    // Better: merge intervals
                    // Since sectors are sorted, we can add them as intervals
                    int start = sectors.get(0);
                    int end = start + 1;
                    for (int j = 1; j < sectors.size(); j++) {
                        if (sectors.get(j) == end) {
                            end++;
                        } else {
                            // Add interval [start, end)
                            addFreeGap(freeGaps, start, end);
                            start = sectors.get(j);
                            end = start + 1;
                        }
                    }
                    addFreeGap(freeGaps, start, end);
                }

            } else if (cmd == 'R') {
                int sector = Integer.parseInt(parts[1]);
                Integer fileId = sectorToFile.get(sector);
                if (fileId == null) {
                    pw.println("E");
                } else {
                    pw.println(fileId);
                }
            }
        }

        pw.flush();
    }

    private static void addFreeGap(TreeSet<int[]> freeGaps, int start, int end) {
        // Merge with existing gaps
        int[] newGap = new int[]{start, end};
        // Find gaps that intersect or are adjacent
        int[] floor = freeGaps.floor(new int[]{start, end});
        int[] ceil = freeGaps.ceiling(new int[]{start, end});

        // Check left merge
        if (floor != null && floor[1] >= start) {
            // Merge
            start = Math.min(start, floor[0]);
            end = Math.max(end, floor[1]);
            freeGaps.remove(floor);
        }
        // Check right merge
        if (ceil != null && ceil[0] <= end) {
            end = Math.max(end, ceil[1]);
            start = Math.min(start, ceil[0]);
            freeGaps.remove(ceil);
        }
        freeGaps.add(new int[]{start, end});
    }
}

