import java.io.*;
import java.util.*;

/*
 * File system simulation on a medium with:
 * - random access read/delete
 * - write only into the first free space found, sequentially from the beginning
 *
 * Commands:
 *   W id size   : write a file with identifier id occupying 'size' sectors
 *   D id        : delete file id
 *   R sector    : report which file id occupies this sector, or 0 if empty
 *
 * Assumptions inferred from the statement:
 * - Storage is unbounded.
 * - Initially empty.
 * - File ids are unique among currently stored files.
 *
 * Approach:
 * Maintain occupied intervals [start, end] for each file in a TreeMap keyed by start.
 * Also maintain free intervals in a TreeSet ordered by start.
 *
 * Writing:
 *   Find the first free interval with length >= size.
 *   If none exists, append after the current maximum occupied end.
 *   If found, allocate from its beginning and shrink/remove the free interval.
 *
 * Deleting:
 *   Remove the file's occupied interval.
 *   Insert that interval into free space, merging with adjacent free intervals.
 *
 * Referencing:
 *   Find the occupied interval with greatest start <= sector and check if it covers sector.
 *
 * Complexity:
 *   Each operation is O(log n).
 */
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');

            StringBuilder sb = new StringBuilder();
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        long nextLong() throws IOException {
            return Long.parseLong(next());
        }
    }

    static class Interval {
        long l, r;
        Interval(long l, long r) {
            this.l = l;
            this.r = r;
        }
    }

    static class FileInfo {
        long start, end;
        long id;
        FileInfo(long start, long end, long id) {
            this.start = start;
            this.end = end;
            this.id = id;
        }
    }

    static TreeMap<Long, FileInfo> filesByStart = new TreeMap<>();
    static HashMap<Long, FileInfo> filesById = new HashMap<>();
    static TreeSet<Interval> free = new TreeSet<>((a, b) -> {
        if (a.l != b.l) return Long.compare(a.l, b.l);
        return Long.compare(a.r, b.r);
    });

    static long maxEnd = 0; // highest occupied sector ever currently in use; 0 means empty

    static void addFree(long l, long r) {
        if (l > r) return;

        Interval cur = new Interval(l, r);

        Interval prev = free.floor(cur);
        if (prev != null && prev.r + 1 >= cur.l) {
            cur.l = Math.min(cur.l, prev.l);
            cur.r = Math.max(cur.r, prev.r);
            free.remove(prev);
        }

        Interval next = free.ceiling(cur);
        while (next != null && next.l <= cur.r + 1) {
            cur.l = Math.min(cur.l, next.l);
            cur.r = Math.max(cur.r, next.r);
            free.remove(next);
            next = free.ceiling(cur);
        }

        free.add(cur);
    }

    static void writeFile(long id, long size) {
        Interval chosen = null;
        for (Interval it : free) {
            if (it.r - it.l + 1 >= size) {
                chosen = it;
                break;
            }
        }

        long l, r;
        if (chosen == null) {
            l = maxEnd + 1;
            r = l + size - 1;
        } else {
            l = chosen.l;
            r = l + size - 1;
            free.remove(chosen);
            if (r < chosen.r) {
                free.add(new Interval(r + 1, chosen.r));
            }
        }

        FileInfo fi = new FileInfo(l, r, id);
        filesByStart.put(l, fi);
        filesById.put(id, fi);
        maxEnd = Math.max(maxEnd, r);
    }

    static void deleteFile(long id) {
        FileInfo fi = filesById.remove(id);
        if (fi == null) return;

        filesByStart.remove(fi.start);
        addFree(fi.start, fi.end);

        // shrink maxEnd if last file(s) removed from the end
        while (maxEnd > 0) {
            Map.Entry<Long, FileInfo> last = filesByStart.lastEntry();
            if (last == null) {
                maxEnd = 0;
                free.clear();
                break;
            }
            maxEnd = last.getValue().end;

            // remove free intervals strictly beyond maxEnd, and trim touching one if needed
            Interval probe = free.ceiling(new Interval(maxEnd + 1, maxEnd + 1));
            while (probe != null) {
                free.remove(probe);
                probe = free.ceiling(new Interval(maxEnd + 1, maxEnd + 1));
            }

            Interval lastFree = free.floor(new Interval(maxEnd, Long.MAX_VALUE));
            if (lastFree != null && lastFree.r > maxEnd) {
                free.remove(lastFree);
                if (lastFree.l <= maxEnd) {
                    free.add(new Interval(lastFree.l, maxEnd));
                }
            }
            break;
        }
    }

    static long reference(long sector) {
        Map.Entry<Long, FileInfo> e = filesByStart.floorEntry(sector);
        if (e == null) return 0;
        FileInfo fi = e.getValue();
        return fi.end >= sector ? fi.id : 0;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        String first = fs.next();
        if (first == null) {
            System.out.print("");
            return;
        }

        int q;
        try {
            q = Integer.parseInt(first);
            for (int i = 0; i < q; i++) {
                String cmd = fs.next();
                if (cmd == null) break;
                char c = cmd.charAt(0);
                if (c == 'W') {
                    long id = fs.nextLong();
                    long size = fs.nextLong();
                    writeFile(id, size);
                } else if (c == 'D') {
                    long id = fs.nextLong();
                    deleteFile(id);
                } else if (c == 'R') {
                    long sector = fs.nextLong();
                    out.append(reference(sector)).append('\n');
                }
            }
        } catch (NumberFormatException ex) {
            // If input does not start with number of commands, process until EOF.
            String cmd = first;
            while (cmd != null) {
                char c = cmd.charAt(0);
                if (c == 'W') {
                    long id = fs.nextLong();
                    long size = fs.nextLong();
                    writeFile(id, size);
                } else if (c == 'D') {
                    long id = fs.nextLong();
                    deleteFile(id);
                } else if (c == 'R') {
                    long sector = fs.nextLong();
                    out.append(reference(sector)).append('\n');
                }
                cmd = fs.next();
            }
        }

        System.out.print(out.toString());
    }
}

