#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_SECTORS 1000000
#define MAX_FILES 100000

typedef struct File {
    int id;
    int start;
    int size;
} File;

typedef struct FreeBlock {
    int start;
    int size;
    struct FreeBlock *next;
} FreeBlock;

File files[MAX_FILES];
int file_count = 0;
FreeBlock *free_list = NULL;
int sector_data[MAX_SECTORS]; // -1 means free, otherwise file id
int total_sectors = 0;

void init_free_list(int total) {
    free_list = (FreeBlock*)malloc(sizeof(FreeBlock));
    free_list->start = 0;
    free_list->size = total;
    free_list->next = NULL;
    total_sectors = total;
    for (int i = 0; i < total; i++) {
        sector_data[i] = -1;
    }
}

void add_free_block(int start, int size) {
    FreeBlock *new_block = (FreeBlock*)malloc(sizeof(FreeBlock));
    new_block->start = start;
    new_block->size = size;
    new_block->next = NULL;

    // Insert in sorted order by start
    FreeBlock *prev = NULL;
    FreeBlock *curr = free_list;
    while (curr != NULL && curr->start < start) {
        prev = curr;
        curr = curr->next;
    }

    if (prev == NULL) {
        new_block->next = free_list;
        free_list = new_block;
    } else {
        new_block->next = curr;
        prev->next = new_block;
    }

    // Merge with previous if adjacent
    if (prev != NULL && prev->start + prev->size == new_block->start) {
        prev->size += new_block->size;
        prev->next = new_block->next;
        free(new_block);
        new_block = prev;
    }

    // Merge with next if adjacent
    if (new_block->next != NULL && new_block->start + new_block->size == new_block->next->start) {
        new_block->size += new_block->next->size;
        FreeBlock *temp = new_block->next;
        new_block->next = temp->next;
        free(temp);
    }
}

int allocate_file(int id, int size) {
    FreeBlock *prev = NULL;
    FreeBlock *curr = free_list;
    while (curr != NULL) {
        if (curr->size >= size) {
            int start = curr->start;
            // Mark sectors
            for (int i = 0; i < size; i++) {
                sector_data[start + i] = id;
            }
            // Update free list
            if (curr->size == size) {
                if (prev == NULL) {
                    free_list = curr->next;
                } else {
                    prev->next = curr->next;
                }
                free(curr);
            } else {
                curr->start += size;
                curr->size -= size;
            }
            // Store file info
            files[file_count].id = id;
            files[file_count].start = start;
            files[file_count].size = size;
            file_count++;
            return start;
        }
        prev = curr;
        curr = curr->next;
    }
    return -1; // No space
}

void delete_file(int id) {
    // Find file by id
    int idx = -1;
    for (int i = 0; i < file_count; i++) {
        if (files[i].id == id) {
            idx = i;
            break;
        }
    }
    if (idx == -1) return;

    int start = files[idx].start;
    int size = files[idx].size;

    // Mark sectors as free
    for (int i = 0; i < size; i++) {
        sector_data[start + i] = -1;
    }

    // Add to free list
    add_free_block(start, size);

    // Remove file from array (swap with last)
    files[idx] = files[file_count - 1];
    file_count--;
}

int main() {
    int n;
    scanf("%d", &n);

    // First pass to find maximum sector needed for initialization
    int max_sector = 0;
    for (int i = 0; i < n; i++) {
        char cmd[10];
        scanf("%s", cmd);
        if (strcmp(cmd, "WRITE") == 0) {
            int id, size;
            scanf("%d %d", &id, &size);
            // We need to know total sectors; assume we allocate sequentially
            // For now, just read and ignore
        } else if (strcmp(cmd, "DELETE") == 0) {
            int id;
            scanf("%d", &id);
        } else if (strcmp(cmd, "READ") == 0) {
            int sector;
            scanf("%d", &sector);
            if (sector > max_sector) max_sector = sector;
        }
    }

    // We don't know total sectors ahead; use dynamic approach
    // Reset and process again with dynamic sector array
    rewind(stdin);
    scanf("%d", &n);

    // Use a dynamic array for sectors, start with 1000 and expand
    int capacity = 1000;
    int *sectors = (int*)malloc(capacity * sizeof(int));
    for (int i = 0; i < capacity; i++) sectors[i] = -1;

    FreeBlock *free_head = (FreeBlock*)malloc(sizeof(FreeBlock));
    free_head->start = 0;
    free_head->size = capacity;
    free_head->next = NULL;

    File *file_arr = NULL;
    int file_cap = 0;
    int file_cnt = 0;

    for (int i = 0; i < n; i++) {
        char cmd[10];
        scanf("%s", cmd);
        if (strcmp(cmd, "WRITE") == 0) {
            int id, size;
            scanf("%d %d", &id, &size);
            // Find first free block that fits
            FreeBlock *prev = NULL;
            FreeBlock *curr = free_head;
            int found = 0;
            while (curr != NULL) {
                if (curr->size >= size) {
                    int start = curr->start;
                    // Check if we need to expand capacity
                    if (start + size > capacity) {
                        // Expand
                        int new_cap = capacity * 2;
                        while (new_cap < start + size) new_cap *= 2;
                        sectors = (int*)realloc(sectors, new_cap * sizeof(int));
                        for (int j = capacity; j < new_cap; j++) sectors[j] = -1;
                        // Update free list: if the last block ends at capacity, extend it
                        FreeBlock *last = free_head;
                        while (last->next != NULL) last = last->next;
                        if (last->start + last->size == capacity) {
                            last->size += (new_cap - capacity);
                        } else {
                            FreeBlock *new_block = (FreeBlock*)malloc(sizeof(FreeBlock));
                            new_block->start = capacity;
                            new_block->size = new_cap - capacity;
                            new_block->next = NULL;
                            last->next = new_block;
                        }
                        capacity = new_cap;
                    }
                    // Mark sectors
                    for (int j = 0; j < size; j++) {
                        sectors[start + j] = id;
                    }
                    // Update free list
                    if (curr->size == size) {
                        if (prev == NULL) {
                            free_head = curr->next;
                        } else {
                            prev->next = curr->next;
                        }
                        free(curr);
                    } else {
                        curr->start += size;
                        curr->size -= size;
                    }
                    // Store file
                    if (file_cnt >= file_cap) {
                        file_cap = file_cap ? file_cap * 2 : 10;
                        file_arr = (File*)realloc(file_arr, file_cap * sizeof(File));
                    }
                    file_arr[file_cnt].id = id;
                    file_arr[file_cnt].start = start;
                    file_arr[file_cnt].size = size;
                    file_cnt++;
                    found = 1;
                    break;
                }
                prev = curr;
                curr = curr->next;
            }
            if (!found) {
                // Should not happen per problem constraints
            }
        } else if (strcmp(cmd, "DELETE") == 0) {
            int id;
            scanf("%d", &id);
            // Find file
            int idx = -1;
            for (int j = 0; j < file_cnt; j++) {
                if (file_arr[j].id == id) {
                    idx = j;
                    break;
                }
            }
            if (idx == -1) continue;
            int start = file_arr[idx].start;
            int size = file_arr[idx].size;
            // Mark sectors free
            for (int j = 0; j < size; j++) {
                sectors[start + j] = -1;
            }
            // Add free block and merge
            FreeBlock *new_block = (FreeBlock*)malloc(sizeof(FreeBlock));
            new_block->start = start;
            new_block->size = size;
            new_block->next = NULL;

            // Insert sorted
            FreeBlock *prev = NULL;
            FreeBlock *curr = free_head;
            while (curr != NULL && curr->start < start) {
                prev = curr;
                curr = curr->next;
            }
            if (prev == NULL) {
                new_block->next = free_head;
                free_head = new_block;
            } else {
                new_block->next = curr;
                prev->next = new_block;
            }
            // Merge with previous
            if (prev != NULL && prev->start + prev->size == new_block->start) {
                prev->size += new_block->size;
                prev->next = new_block->next;
                free(new_block);
                new_block = prev;
            }
            // Merge with next
            if (new_block->next != NULL && new_block->start + new_block->size == new_block->next->start) {
                new_block->size += new_block->next->size;
                FreeBlock *temp = new_block->next;
                new_block->next = temp->next;
                free(temp);
            }

            // Remove file from array
            file_arr[idx] = file_arr[file_cnt - 1];
            file_cnt--;
        } else if (strcmp(cmd, "READ") == 0) {
            int sector;
            scanf("%d", &sector);
            // Ensure capacity
            if (sector >= capacity) {
                int new_cap = capacity * 2;
                while (new_cap <= sector) new_cap *= 2;
                sectors = (int*)realloc(sectors, new_cap * sizeof(int));
                for (int j = capacity; j < new_cap; j++) sectors[j] = -1;
                // Update free list: extend last block if adjacent
                FreeBlock *last = free_head;
                while (last->next != NULL) last = last->next;
                if (last->start + last->size == capacity) {
                    last->size += (new_cap - capacity);
                } else {
                    FreeBlock *new_block = (FreeBlock*)malloc(sizeof(FreeBlock));
                    new_block->start = capacity;
                    new_block->size = new_cap - capacity;
                    new_block->next = NULL;
                    last->next = new_block;
                }
                capacity = new_cap;
            }
            printf("%d\n", sectors[sector]);
        }
    }

    // Free memory (not strictly necessary for competitive programming)
    free(sectors);
    FreeBlock *curr = free_head;
    while (curr != NULL) {
        FreeBlock *temp = curr;
        curr = curr->next;
        free(temp);
    }
    free(file_arr);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef long long ll;

typedef struct Seg {
    ll l, r;               // inclusive
    struct Seg *prev, *next;
} Seg;

typedef struct FileNode {
    int id;
    ll start, len;
    struct FileNode *prev, *next;
} FileNode;

static Seg *freeHead = NULL;
static FileNode *fileHead = NULL, *fileTail = NULL;

/* ---------- Free segment list utilities ---------- */

static Seg* newSeg(ll l, ll r) {
    Seg *s = (Seg*)malloc(sizeof(Seg));
    s->l = l; s->r = r;
    s->prev = s->next = NULL;
    return s;
}

static void insertFreeSorted(Seg *node) {
    if (!freeHead) {
        freeHead = node;
        return;
    }
    Seg *cur = freeHead, *pr = NULL;
    while (cur && cur->l < node->l) {
        pr = cur;
        cur = cur->next;
    }
    node->prev = pr;
    node->next = cur;
    if (pr) pr->next = node;
    else freeHead = node;
    if (cur) cur->prev = node;

    // merge with prev
    if (node->prev && node->prev->r + 1 >= node->l) {
        if (node->prev->r < node->r) node->prev->r = node->r;
        node->prev->next = node->next;
        if (node->next) node->next->prev = node->prev;
        Seg *tmp = node;
        node = node->prev;
        free(tmp);
    }
    // merge with next
    if (node->next && node->r + 1 >= node->next->l) {
        if (node->r < node->next->r) node->r = node->next->r;
        Seg *tmp = node->next;
        node->next = tmp->next;
        if (tmp->next) tmp->next->prev = node;
        free(tmp);
    }
}

static ll allocateBlock(ll len) {
    Seg *cur = freeHead;
    while (cur) {
        ll sz = cur->r - cur->l + 1;
        if (sz >= len) {
            ll st = cur->l;
            cur->l += len;
            if (cur->l > cur->r) {
                if (cur->prev) cur->prev->next = cur->next;
                else freeHead = cur->next;
                if (cur->next) cur->next->prev = cur->prev;
                free(cur);
            }
            return st;
        }
        cur = cur->next;
    }
    return -1;
}

/* ---------- File list utilities ---------- */

static FileNode* newFile(int id, ll start, ll len) {
    FileNode *f = (FileNode*)malloc(sizeof(FileNode));
    f->id = id; f->start = start; f->len = len;
    f->prev = f->next = NULL;
    return f;
}

static void appendFile(FileNode *f) {
    if (!fileHead) {
        fileHead = fileTail = f;
    } else {
        fileTail->next = f;
        f->prev = fileTail;
        fileTail = f;
    }
}

static FileNode* findFileById(int id) {
    FileNode *cur = fileHead;
    while (cur) {
        if (cur->id == id) return cur;
        cur = cur->next;
    }
    return NULL;
}

static void removeFile(FileNode *f) {
    if (f->prev) f->prev->next = f->next;
    else fileHead = f->next;
    if (f->next) f->next->prev = f->prev;
    else fileTail = f->prev;
}

/* ---------- Main ---------- */

int main(void) {
    int q;
    if (scanf("%d", &q) != 1) return 0;

    ll endPos = 0; // next unwritten position

    for (int i = 0; i < q; i++) {
        char cmd[32];
        scanf("%s", cmd);

        if (strcmp(cmd, "write") == 0) {
            int id;
            ll len;
            scanf("%d %lld", &id, &len);

            ll st = allocateBlock(len);
            if (st == -1) {
                st = endPos;
                endPos += len;
            }
            appendFile(newFile(id, st, len));
        }
        else if (strcmp(cmd, "delete") == 0) {
            int id;
            scanf("%d", &id);
            FileNode *f = findFileById(id);
            if (f) {
                insertFreeSorted(newSeg(f->start, f->start + f->len - 1));
                removeFile(f);
                free(f);
            }
        }
        else if (strcmp(cmd, "reference") == 0) {
            ll x;
            scanf("%lld", &x);
            FileNode *cur = fileHead;
            int ans = -1;
            while (cur) {
                if (cur->start <= x && x < cur->start + cur->len) {
                    ans = cur->id;
                    break;
                }
                cur = cur->next;
            }
            printf("%d\n", ans);
        }
    }

    return 0;
}
